-- Imports the Open Food Facts CSV export into the foods table.
-- Run from api/: npm run db:import-off (expects the CSV at ~/Downloads, override with OFF_CSV).
-- Rows need a product name and a plausible kcal/100g value; duplicate barcodes keep the latest edit.
-- Previously imported rows (code IS NOT NULL) are replaced; foods created through the API are kept.

INSTALL postgres;
LOAD postgres;
SET TimeZone = 'UTC';
SET preserve_insertion_order = false;
-- Works around a DuckDB 1.5 internal error when optimizing the QUALIFY dedupe below.
SET disabled_optimizers = 'top_n_window_elimination';

ATTACH 'postgresql://postgres:postgres@localhost:5432/foodtracker' AS pg (TYPE postgres);

CREATE TEMP TABLE off_import AS
SELECT
  replace(trim("product_name"), chr(0), '') AS name,
  round(TRY_CAST("energy-kcal_100g" AS DOUBLE))::INTEGER AS calories,
  "code" AS "code",
  replace("url", chr(0), '') AS "url",
  replace("creator", chr(0), '') AS "creator",
  TRY_CAST("created_t" AS BIGINT) AS "created_t",
  TRY_CAST("created_datetime" AS TIMESTAMPTZ) AS "created_datetime",
  TRY_CAST("last_modified_t" AS BIGINT) AS "last_modified_t",
  TRY_CAST("last_modified_datetime" AS TIMESTAMPTZ) AS "last_modified_datetime",
  replace("last_modified_by", chr(0), '') AS "last_modified_by",
  TRY_CAST("last_updated_t" AS BIGINT) AS "last_updated_t",
  TRY_CAST("last_updated_datetime" AS TIMESTAMPTZ) AS "last_updated_datetime",
  replace("product_name", chr(0), '') AS "product_name",
  replace("abbreviated_product_name", chr(0), '') AS "abbreviated_product_name",
  replace("generic_name", chr(0), '') AS "generic_name",
  replace("quantity", chr(0), '') AS "quantity",
  replace("packaging", chr(0), '') AS "packaging",
  replace("packaging_tags", chr(0), '') AS "packaging_tags",
  replace("packaging_en", chr(0), '') AS "packaging_en",
  replace("packaging_text", chr(0), '') AS "packaging_text",
  replace("brands", chr(0), '') AS "brands",
  replace("brands_tags", chr(0), '') AS "brands_tags",
  replace("brands_en", chr(0), '') AS "brands_en",
  replace("categories", chr(0), '') AS "categories",
  replace("categories_tags", chr(0), '') AS "categories_tags",
  replace("categories_en", chr(0), '') AS "categories_en",
  replace("origins", chr(0), '') AS "origins",
  replace("origins_tags", chr(0), '') AS "origins_tags",
  replace("origins_en", chr(0), '') AS "origins_en",
  replace("manufacturing_places", chr(0), '') AS "manufacturing_places",
  replace("manufacturing_places_tags", chr(0), '') AS "manufacturing_places_tags",
  replace("labels", chr(0), '') AS "labels",
  replace("labels_tags", chr(0), '') AS "labels_tags",
  replace("labels_en", chr(0), '') AS "labels_en",
  replace("emb_codes", chr(0), '') AS "emb_codes",
  replace("emb_codes_tags", chr(0), '') AS "emb_codes_tags",
  replace("first_packaging_code_geo", chr(0), '') AS "first_packaging_code_geo",
  replace("cities", chr(0), '') AS "cities",
  replace("cities_tags", chr(0), '') AS "cities_tags",
  replace("purchase_places", chr(0), '') AS "purchase_places",
  replace("stores", chr(0), '') AS "stores",
  replace("countries", chr(0), '') AS "countries",
  replace("countries_tags", chr(0), '') AS "countries_tags",
  replace("countries_en", chr(0), '') AS "countries_en",
  replace("ingredients_text", chr(0), '') AS "ingredients_text",
  replace("ingredients_tags", chr(0), '') AS "ingredients_tags",
  replace("ingredients_analysis_tags", chr(0), '') AS "ingredients_analysis_tags",
  replace("allergens", chr(0), '') AS "allergens",
  replace("allergens_en", chr(0), '') AS "allergens_en",
  replace("traces", chr(0), '') AS "traces",
  replace("traces_tags", chr(0), '') AS "traces_tags",
  replace("traces_en", chr(0), '') AS "traces_en",
  replace("serving_size", chr(0), '') AS "serving_size",
  TRY_CAST("serving_quantity" AS DOUBLE) AS "serving_quantity",
  replace("no_nutrition_data", chr(0), '') AS "no_nutrition_data",
  TRY_CAST("additives_n" AS INTEGER) AS "additives_n",
  replace("additives", chr(0), '') AS "additives",
  replace("additives_tags", chr(0), '') AS "additives_tags",
  replace("additives_en", chr(0), '') AS "additives_en",
  TRY_CAST("nutriscore_score" AS INTEGER) AS "nutriscore_score",
  replace("nutriscore_grade", chr(0), '') AS "nutriscore_grade",
  TRY_CAST("nova_group" AS INTEGER) AS "nova_group",
  replace("pnns_groups_1", chr(0), '') AS "pnns_groups_1",
  replace("pnns_groups_2", chr(0), '') AS "pnns_groups_2",
  replace("food_groups", chr(0), '') AS "food_groups",
  replace("food_groups_tags", chr(0), '') AS "food_groups_tags",
  replace("food_groups_en", chr(0), '') AS "food_groups_en",
  replace("states", chr(0), '') AS "states",
  replace("states_tags", chr(0), '') AS "states_tags",
  replace("states_en", chr(0), '') AS "states_en",
  replace("brand_owner", chr(0), '') AS "brand_owner",
  TRY_CAST("environmental_score_score" AS DOUBLE) AS "environmental_score_score",
  replace("environmental_score_grade", chr(0), '') AS "environmental_score_grade",
  replace("nutrient_levels_tags", chr(0), '') AS "nutrient_levels_tags",
  TRY_CAST("product_quantity" AS DOUBLE) AS "product_quantity",
  replace("owner", chr(0), '') AS "owner",
  replace("data_quality_errors_tags", chr(0), '') AS "data_quality_errors_tags",
  TRY_CAST("unique_scans_n" AS INTEGER) AS "unique_scans_n",
  replace("popularity_tags", chr(0), '') AS "popularity_tags",
  TRY_CAST("completeness" AS DOUBLE) AS "completeness",
  TRY_CAST("last_image_t" AS BIGINT) AS "last_image_t",
  TRY_CAST("last_image_datetime" AS TIMESTAMPTZ) AS "last_image_datetime",
  replace("main_category", chr(0), '') AS "main_category",
  replace("main_category_en", chr(0), '') AS "main_category_en",
  replace("image_url", chr(0), '') AS "image_url",
  replace("image_small_url", chr(0), '') AS "image_small_url",
  replace("image_ingredients_url", chr(0), '') AS "image_ingredients_url",
  replace("image_ingredients_small_url", chr(0), '') AS "image_ingredients_small_url",
  replace("image_nutrition_url", chr(0), '') AS "image_nutrition_url",
  replace("image_nutrition_small_url", chr(0), '') AS "image_nutrition_small_url",
  TRY_CAST("energy-kj_100g" AS DOUBLE) AS "energy_kj_100g",
  TRY_CAST("energy-kcal_100g" AS DOUBLE) AS "energy_kcal_100g",
  TRY_CAST("energy_100g" AS DOUBLE) AS "energy_100g",
  TRY_CAST("energy-from-fat_100g" AS DOUBLE) AS "energy_from_fat_100g",
  TRY_CAST("fat_100g" AS DOUBLE) AS "fat_100g",
  TRY_CAST("saturated-fat_100g" AS DOUBLE) AS "saturated_fat_100g",
  TRY_CAST("butyric-acid_100g" AS DOUBLE) AS "butyric_acid_100g",
  TRY_CAST("caproic-acid_100g" AS DOUBLE) AS "caproic_acid_100g",
  TRY_CAST("caprylic-acid_100g" AS DOUBLE) AS "caprylic_acid_100g",
  TRY_CAST("capric-acid_100g" AS DOUBLE) AS "capric_acid_100g",
  TRY_CAST("lauric-acid_100g" AS DOUBLE) AS "lauric_acid_100g",
  TRY_CAST("myristic-acid_100g" AS DOUBLE) AS "myristic_acid_100g",
  TRY_CAST("palmitic-acid_100g" AS DOUBLE) AS "palmitic_acid_100g",
  TRY_CAST("stearic-acid_100g" AS DOUBLE) AS "stearic_acid_100g",
  TRY_CAST("arachidic-acid_100g" AS DOUBLE) AS "arachidic_acid_100g",
  TRY_CAST("behenic-acid_100g" AS DOUBLE) AS "behenic_acid_100g",
  TRY_CAST("lignoceric-acid_100g" AS DOUBLE) AS "lignoceric_acid_100g",
  TRY_CAST("cerotic-acid_100g" AS DOUBLE) AS "cerotic_acid_100g",
  TRY_CAST("montanic-acid_100g" AS DOUBLE) AS "montanic_acid_100g",
  TRY_CAST("melissic-acid_100g" AS DOUBLE) AS "melissic_acid_100g",
  TRY_CAST("unsaturated-fat_100g" AS DOUBLE) AS "unsaturated_fat_100g",
  TRY_CAST("monounsaturated-fat_100g" AS DOUBLE) AS "monounsaturated_fat_100g",
  TRY_CAST("omega-9-fat_100g" AS DOUBLE) AS "omega_9_fat_100g",
  TRY_CAST("polyunsaturated-fat_100g" AS DOUBLE) AS "polyunsaturated_fat_100g",
  TRY_CAST("omega-3-fat_100g" AS DOUBLE) AS "omega_3_fat_100g",
  TRY_CAST("omega-6-fat_100g" AS DOUBLE) AS "omega_6_fat_100g",
  TRY_CAST("alpha-linolenic-acid_100g" AS DOUBLE) AS "alpha_linolenic_acid_100g",
  TRY_CAST("eicosapentaenoic-acid_100g" AS DOUBLE) AS "eicosapentaenoic_acid_100g",
  TRY_CAST("docosahexaenoic-acid_100g" AS DOUBLE) AS "docosahexaenoic_acid_100g",
  TRY_CAST("linoleic-acid_100g" AS DOUBLE) AS "linoleic_acid_100g",
  TRY_CAST("arachidonic-acid_100g" AS DOUBLE) AS "arachidonic_acid_100g",
  TRY_CAST("gamma-linolenic-acid_100g" AS DOUBLE) AS "gamma_linolenic_acid_100g",
  TRY_CAST("dihomo-gamma-linolenic-acid_100g" AS DOUBLE) AS "dihomo_gamma_linolenic_acid_100g",
  TRY_CAST("oleic-acid_100g" AS DOUBLE) AS "oleic_acid_100g",
  TRY_CAST("elaidic-acid_100g" AS DOUBLE) AS "elaidic_acid_100g",
  TRY_CAST("gondoic-acid_100g" AS DOUBLE) AS "gondoic_acid_100g",
  TRY_CAST("mead-acid_100g" AS DOUBLE) AS "mead_acid_100g",
  TRY_CAST("erucic-acid_100g" AS DOUBLE) AS "erucic_acid_100g",
  TRY_CAST("nervonic-acid_100g" AS DOUBLE) AS "nervonic_acid_100g",
  TRY_CAST("trans-fat_100g" AS DOUBLE) AS "trans_fat_100g",
  TRY_CAST("cholesterol_100g" AS DOUBLE) AS "cholesterol_100g",
  TRY_CAST("carbohydrates_100g" AS DOUBLE) AS "carbohydrates_100g",
  TRY_CAST("sugars_100g" AS DOUBLE) AS "sugars_100g",
  TRY_CAST("added-sugars_100g" AS DOUBLE) AS "added_sugars_100g",
  TRY_CAST("sucrose_100g" AS DOUBLE) AS "sucrose_100g",
  TRY_CAST("glucose_100g" AS DOUBLE) AS "glucose_100g",
  TRY_CAST("fructose_100g" AS DOUBLE) AS "fructose_100g",
  TRY_CAST("galactose_100g" AS DOUBLE) AS "galactose_100g",
  TRY_CAST("lactose_100g" AS DOUBLE) AS "lactose_100g",
  TRY_CAST("maltose_100g" AS DOUBLE) AS "maltose_100g",
  TRY_CAST("maltodextrins_100g" AS DOUBLE) AS "maltodextrins_100g",
  TRY_CAST("psicose_100g" AS DOUBLE) AS "psicose_100g",
  TRY_CAST("starch_100g" AS DOUBLE) AS "starch_100g",
  TRY_CAST("polyols_100g" AS DOUBLE) AS "polyols_100g",
  TRY_CAST("erythritol_100g" AS DOUBLE) AS "erythritol_100g",
  TRY_CAST("isomalt_100g" AS DOUBLE) AS "isomalt_100g",
  TRY_CAST("maltitol_100g" AS DOUBLE) AS "maltitol_100g",
  TRY_CAST("sorbitol_100g" AS DOUBLE) AS "sorbitol_100g",
  TRY_CAST("fiber_100g" AS DOUBLE) AS "fiber_100g",
  TRY_CAST("soluble-fiber_100g" AS DOUBLE) AS "soluble_fiber_100g",
  TRY_CAST("polydextrose_100g" AS DOUBLE) AS "polydextrose_100g",
  TRY_CAST("insoluble-fiber_100g" AS DOUBLE) AS "insoluble_fiber_100g",
  TRY_CAST("proteins_100g" AS DOUBLE) AS "proteins_100g",
  TRY_CAST("casein_100g" AS DOUBLE) AS "casein_100g",
  TRY_CAST("serum-proteins_100g" AS DOUBLE) AS "serum_proteins_100g",
  TRY_CAST("nucleotides_100g" AS DOUBLE) AS "nucleotides_100g",
  TRY_CAST("salt_100g" AS DOUBLE) AS "salt_100g",
  TRY_CAST("added-salt_100g" AS DOUBLE) AS "added_salt_100g",
  TRY_CAST("sodium_100g" AS DOUBLE) AS "sodium_100g",
  TRY_CAST("alcohol_100g" AS DOUBLE) AS "alcohol_100g",
  TRY_CAST("vitamin-a_100g" AS DOUBLE) AS "vitamin_a_100g",
  TRY_CAST("beta-carotene_100g" AS DOUBLE) AS "beta_carotene_100g",
  TRY_CAST("vitamin-d_100g" AS DOUBLE) AS "vitamin_d_100g",
  TRY_CAST("vitamin-e_100g" AS DOUBLE) AS "vitamin_e_100g",
  TRY_CAST("vitamin-k_100g" AS DOUBLE) AS "vitamin_k_100g",
  TRY_CAST("vitamin-c_100g" AS DOUBLE) AS "vitamin_c_100g",
  TRY_CAST("vitamin-b1_100g" AS DOUBLE) AS "vitamin_b1_100g",
  TRY_CAST("vitamin-b2_100g" AS DOUBLE) AS "vitamin_b2_100g",
  TRY_CAST("vitamin-pp_100g" AS DOUBLE) AS "vitamin_pp_100g",
  TRY_CAST("vitamin-b6_100g" AS DOUBLE) AS "vitamin_b6_100g",
  TRY_CAST("vitamin-b9_100g" AS DOUBLE) AS "vitamin_b9_100g",
  TRY_CAST("folates_100g" AS DOUBLE) AS "folates_100g",
  TRY_CAST("vitamin-b12_100g" AS DOUBLE) AS "vitamin_b12_100g",
  TRY_CAST("biotin_100g" AS DOUBLE) AS "biotin_100g",
  TRY_CAST("pantothenic-acid_100g" AS DOUBLE) AS "pantothenic_acid_100g",
  TRY_CAST("silica_100g" AS DOUBLE) AS "silica_100g",
  TRY_CAST("bicarbonate_100g" AS DOUBLE) AS "bicarbonate_100g",
  TRY_CAST("potassium_100g" AS DOUBLE) AS "potassium_100g",
  TRY_CAST("chloride_100g" AS DOUBLE) AS "chloride_100g",
  TRY_CAST("calcium_100g" AS DOUBLE) AS "calcium_100g",
  TRY_CAST("phosphorus_100g" AS DOUBLE) AS "phosphorus_100g",
  TRY_CAST("iron_100g" AS DOUBLE) AS "iron_100g",
  TRY_CAST("magnesium_100g" AS DOUBLE) AS "magnesium_100g",
  TRY_CAST("zinc_100g" AS DOUBLE) AS "zinc_100g",
  TRY_CAST("copper_100g" AS DOUBLE) AS "copper_100g",
  TRY_CAST("manganese_100g" AS DOUBLE) AS "manganese_100g",
  TRY_CAST("fluoride_100g" AS DOUBLE) AS "fluoride_100g",
  TRY_CAST("selenium_100g" AS DOUBLE) AS "selenium_100g",
  TRY_CAST("chromium_100g" AS DOUBLE) AS "chromium_100g",
  TRY_CAST("molybdenum_100g" AS DOUBLE) AS "molybdenum_100g",
  TRY_CAST("iodine_100g" AS DOUBLE) AS "iodine_100g",
  TRY_CAST("caffeine_100g" AS DOUBLE) AS "caffeine_100g",
  TRY_CAST("taurine_100g" AS DOUBLE) AS "taurine_100g",
  TRY_CAST("methylsulfonylmethane_100g" AS DOUBLE) AS "methylsulfonylmethane_100g",
  TRY_CAST("hydroxymethylbutyrate_100g" AS DOUBLE) AS "hydroxymethylbutyrate_100g",
  TRY_CAST("ph_100g" AS DOUBLE) AS "ph_100g",
  TRY_CAST("fruits-vegetables-legumes_100g" AS DOUBLE) AS "fruits_vegetables_legumes_100g",
  TRY_CAST("collagen-meat-protein-ratio_100g" AS DOUBLE) AS "collagen_meat_protein_ratio_100g",
  TRY_CAST("cocoa_100g" AS DOUBLE) AS "cocoa_100g",
  TRY_CAST("chlorophyl_100g" AS DOUBLE) AS "chlorophyl_100g",
  TRY_CAST("carbon-footprint_100g" AS DOUBLE) AS "carbon_footprint_100g",
  TRY_CAST("glycemic-index_100g" AS DOUBLE) AS "glycemic_index_100g",
  TRY_CAST("water-hardness_100g" AS DOUBLE) AS "water_hardness_100g",
  TRY_CAST("choline_100g" AS DOUBLE) AS "choline_100g",
  TRY_CAST("phylloquinone_100g" AS DOUBLE) AS "phylloquinone_100g",
  TRY_CAST("beta-glucan_100g" AS DOUBLE) AS "beta_glucan_100g",
  TRY_CAST("inositol_100g" AS DOUBLE) AS "inositol_100g",
  TRY_CAST("carnitine_100g" AS DOUBLE) AS "carnitine_100g",
  TRY_CAST("sulphate_100g" AS DOUBLE) AS "sulphate_100g",
  TRY_CAST("nitrate_100g" AS DOUBLE) AS "nitrate_100g",
  TRY_CAST("acidity_100g" AS DOUBLE) AS "acidity_100g",
  TRY_CAST("carbohydrates-total_100g" AS DOUBLE) AS "carbohydrates_total_100g",
  TRY_CAST("water_100g" AS DOUBLE) AS "water_100g"
FROM read_csv(
  coalesce(nullif(getenv('OFF_CSV'), ''), getenv('HOME') || '/Downloads/en.openfoodfacts.org.products.csv'),
  delim = '\t', quote = '', escape = '', header = true, all_varchar = true, strict_mode = false
)
WHERE code IS NOT NULL
  AND nullif(trim("product_name"), '') IS NOT NULL
  AND TRY_CAST("energy-kcal_100g" AS DOUBLE) BETWEEN 0 AND 1000
QUALIFY row_number() OVER (PARTITION BY code ORDER BY TRY_CAST("last_modified_t" AS BIGINT) DESC NULLS LAST) = 1;

SELECT count(*) AS rows_to_import FROM off_import;

BEGIN;
DELETE FROM pg.public.foods WHERE code IS NOT NULL;
INSERT INTO pg.public.foods (name, calories, "code", "url", "creator", "created_t", "created_datetime", "last_modified_t", "last_modified_datetime", "last_modified_by", "last_updated_t", "last_updated_datetime", "product_name", "abbreviated_product_name", "generic_name", "quantity", "packaging", "packaging_tags", "packaging_en", "packaging_text", "brands", "brands_tags", "brands_en", "categories", "categories_tags", "categories_en", "origins", "origins_tags", "origins_en", "manufacturing_places", "manufacturing_places_tags", "labels", "labels_tags", "labels_en", "emb_codes", "emb_codes_tags", "first_packaging_code_geo", "cities", "cities_tags", "purchase_places", "stores", "countries", "countries_tags", "countries_en", "ingredients_text", "ingredients_tags", "ingredients_analysis_tags", "allergens", "allergens_en", "traces", "traces_tags", "traces_en", "serving_size", "serving_quantity", "no_nutrition_data", "additives_n", "additives", "additives_tags", "additives_en", "nutriscore_score", "nutriscore_grade", "nova_group", "pnns_groups_1", "pnns_groups_2", "food_groups", "food_groups_tags", "food_groups_en", "states", "states_tags", "states_en", "brand_owner", "environmental_score_score", "environmental_score_grade", "nutrient_levels_tags", "product_quantity", "owner", "data_quality_errors_tags", "unique_scans_n", "popularity_tags", "completeness", "last_image_t", "last_image_datetime", "main_category", "main_category_en", "image_url", "image_small_url", "image_ingredients_url", "image_ingredients_small_url", "image_nutrition_url", "image_nutrition_small_url", "energy_kj_100g", "energy_kcal_100g", "energy_100g", "energy_from_fat_100g", "fat_100g", "saturated_fat_100g", "butyric_acid_100g", "caproic_acid_100g", "caprylic_acid_100g", "capric_acid_100g", "lauric_acid_100g", "myristic_acid_100g", "palmitic_acid_100g", "stearic_acid_100g", "arachidic_acid_100g", "behenic_acid_100g", "lignoceric_acid_100g", "cerotic_acid_100g", "montanic_acid_100g", "melissic_acid_100g", "unsaturated_fat_100g", "monounsaturated_fat_100g", "omega_9_fat_100g", "polyunsaturated_fat_100g", "omega_3_fat_100g", "omega_6_fat_100g", "alpha_linolenic_acid_100g", "eicosapentaenoic_acid_100g", "docosahexaenoic_acid_100g", "linoleic_acid_100g", "arachidonic_acid_100g", "gamma_linolenic_acid_100g", "dihomo_gamma_linolenic_acid_100g", "oleic_acid_100g", "elaidic_acid_100g", "gondoic_acid_100g", "mead_acid_100g", "erucic_acid_100g", "nervonic_acid_100g", "trans_fat_100g", "cholesterol_100g", "carbohydrates_100g", "sugars_100g", "added_sugars_100g", "sucrose_100g", "glucose_100g", "fructose_100g", "galactose_100g", "lactose_100g", "maltose_100g", "maltodextrins_100g", "psicose_100g", "starch_100g", "polyols_100g", "erythritol_100g", "isomalt_100g", "maltitol_100g", "sorbitol_100g", "fiber_100g", "soluble_fiber_100g", "polydextrose_100g", "insoluble_fiber_100g", "proteins_100g", "casein_100g", "serum_proteins_100g", "nucleotides_100g", "salt_100g", "added_salt_100g", "sodium_100g", "alcohol_100g", "vitamin_a_100g", "beta_carotene_100g", "vitamin_d_100g", "vitamin_e_100g", "vitamin_k_100g", "vitamin_c_100g", "vitamin_b1_100g", "vitamin_b2_100g", "vitamin_pp_100g", "vitamin_b6_100g", "vitamin_b9_100g", "folates_100g", "vitamin_b12_100g", "biotin_100g", "pantothenic_acid_100g", "silica_100g", "bicarbonate_100g", "potassium_100g", "chloride_100g", "calcium_100g", "phosphorus_100g", "iron_100g", "magnesium_100g", "zinc_100g", "copper_100g", "manganese_100g", "fluoride_100g", "selenium_100g", "chromium_100g", "molybdenum_100g", "iodine_100g", "caffeine_100g", "taurine_100g", "methylsulfonylmethane_100g", "hydroxymethylbutyrate_100g", "ph_100g", "fruits_vegetables_legumes_100g", "collagen_meat_protein_ratio_100g", "cocoa_100g", "chlorophyl_100g", "carbon_footprint_100g", "glycemic_index_100g", "water_hardness_100g", "choline_100g", "phylloquinone_100g", "beta_glucan_100g", "inositol_100g", "carnitine_100g", "sulphate_100g", "nitrate_100g", "acidity_100g", "carbohydrates_total_100g", "water_100g")
SELECT * FROM off_import;
COMMIT;

SELECT count(*) AS foods_in_postgres FROM pg.public.foods;
